<?php declare(strict_types=1); namespace Annam; $title='Checkout'; ?>
<section class="wrap php-store-section"><h1>Delivery details</h1><p>Meals require an approved delivery area. Snacks outside Chennai use courier delivery; courier charges are payable separately after dispatch.</p><form method="post" class="php-white php-checkout"><?= csrf() ?><div class="o-grid-form"><?php foreach(['name'=>'Full name','phone'=>'Mobile number','email'=>'Email (optional)','line1'=>'Door number & street','line2'=>'Apartment / locality (optional)','landmark'=>'Landmark (optional)','city'=>'City','state'=>'State / region','country'=>'Country','pincode'=>'Pincode / postal code'] as $key=>$label): ?><label class="o-field"><span><?= e($label) ?></span><input name="<?= e($key) ?>" value="<?= e($_POST[$key]??(['country'=>'India','state'=>'Tamil Nadu'][$key]??'')) ?>" <?= in_array($key,['email','line2','landmark'])?'':'required' ?> <?= $key==='email'?'type="email"':($key==='phone'?'type="tel"':'') ?> maxlength="<?= $key==='pincode'?20:($key==='phone'?20:200) ?>"></label><?php endforeach; ?>
<label class="o-field"><span>Delivery area</span><select name="zone_id"><option value="">Select automatically from pincode</option><?php foreach($areas as $area): ?><option value="<?= e($area['id']) ?>"><?= e($area['pincode'].' · '.$area['area_name']) ?></option><?php endforeach; ?></select></label><label class="o-field"><span>Payment</span><select name="payment_method" required><?php foreach($choices as $key=>$label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label></div><p>Items subtotal: <strong><?= Money::display($quote['subtotal']) ?></strong>. Delivery and applicable taxes appear on the next step.</p><button class="btn btn-primary" <?= !$choices?'disabled':'' ?>>Review order →</button></form></section>
